// v211_jump_steiner_collection.cpp
// v211: 同色3〜6塔の集荷で、ジャンプ経路と合流先を部分集合DPにより共同で選ぶ。
// 直接の親はv210。集荷候補選別、2塔構築、LNS、NN、時間設定を保持する。
// 添付原版の処理と数値を両モードで保持し、この先頭コメントだけ整理した。
// 添付元SHA-256: fd77f005445d0ea191d9f7f743dfbbbd992fb1f2068dac9ed9d674b11d943889

// A fixed-background collection model. All selected loads have one color.
// Conservative total-capacity checks allow different DP branches to cross:
// a waiting selected load can stay below the moving load of the same color.
struct JumpCollectionStats {
    uint64_t calls=0,completed=0,deadlines=0,budget_skips=0,large_skips=0;
    uint64_t improved_plans=0,changed_roots=0,fixed_root_improvements=0;
    uint64_t fixed_root_saved=0,subsets=0,adopted=0,adopted_jumps=0;
    uint64_t adopted_changed_roots=0,adopted_gain=0;
    double seconds=0;
} jump_collection_stats;

class JumpCollectionPlanner {
#ifdef AHC072_MONO_COLLECTION_PROBE
    friend struct MonoCollectionProbe;
#endif
    struct Edge {int16_t q;uint8_t d,l;};
    struct Action {int16_t previous=-1;uint8_t part=0,d=0,l=0;};
    array<array<Edge,32>,max_cells> edges{};
    array<uint8_t,max_cells> degrees{};
    vector<int16_t> cost;
    vector<Action> action;
    vector<int> queue;
    array<int,64> amount{};
    array<int,max_cells> background{};
    int floors=0,masks=0;
public:
    // Keep the existing feasible plan as an incumbent; a partial DP never
    // replaces it. Errors in reconstruction propagate rather than being hidden.
    MergePlan plan(const State& initial,const array<int,8>& sources,int count,int pieces,
                   int color,int old,const double* weight,double deadline,
                   const MergePlan& incumbent,int& gain) {
        ++jump_collection_stats.calls;
        MergePlan result=incumbent;
        floors=board_info.cell_count;masks=1<<count;
        for(int p=0;p<floors;p++)background[p]=height(initial[p]);
        amount.fill(0);
        for(int i=0;i<count;i++) {
            background[sources[i]]=0;
            amount[1<<i]=height(initial[sources[i]]);
        }
        for(int mask=1;mask<masks;mask++)if(mask&(mask-1))
            amount[mask]=amount[mask&(mask-1)]+amount[mask&-mask];
        if(amount[masks-1]!=pieces)throw logic_error("collection amount mismatch");
        auto allowed=[&](int p){return background[p]+pieces<=8&&board_info.nest_code[p]!=color;};
        degrees.fill(0);
        for(int p=0;p<floors;p++)if(allowed(p)) {
            for(int d=0;d<4;d++)for(int l=1;l<=min(background[p]+1,int(board_info.ray_count[p][d]));l++) {
                int q=board_info.ray[p][d][l];
                if(allowed(q))edges[p][degrees[p]++]={int16_t(q),uint8_t(d),uint8_t(l)};
            }
        }
        cost.assign(masks*floors,int16_t(infinite_cost));
        action.assign(masks*floors,Action{});
        queue.clear();queue.reserve(2*floors);
        auto expired=[&](){
            if(time_keeper.exact_elapsed_sec()<deadline)return false;
            ++jump_collection_stats.deadlines;return true;
        };
        auto push=[&](int p,int value){
            queue.push_back(value*floors+p);
            push_heap(queue.begin(),queue.end(),greater<int>());
        };
        for(int mask=1;mask<masks;mask++) {
            if(expired())return result;
            ++jump_collection_stats.subsets;
            const int offset=mask*floors;
            if(!(mask&(mask-1))) {
                const int source=sources[__builtin_ctz(unsigned(mask))];
                cost[offset+source]=0;
            } else {
                for(int part=(mask-1)&mask;part;part=(part-1)&mask) {
                    const int other=mask^part;
                    if(part>other)continue;
                    const int a=part*floors,b=other*floors;
                    for(int p=0;p<floors;p++) {
                        const int value=int(cost[a+p])+cost[b+p];
                        if(value<cost[offset+p]) {
                            cost[offset+p]=int16_t(value);
                            action[offset+p]={-1,uint8_t(part),0,0};
                        }
                    }
                }
            }
            queue.clear();
            for(int p=0;p<floors;p++)if(cost[offset+p]<infinite_cost)push(p,cost[offset+p]);
            int expanded=0;
            while(!queue.empty()) {
                pop_heap(queue.begin(),queue.end(),greater<int>());
                const int key=queue.back();queue.pop_back();
                const int p=key%floors,value=key/floors;
                if(value!=cost[offset+p])continue;
                if((++expanded&127)==0&&expired())return result;
                for(int j=0;j<degrees[p];j++) {
                    const auto e=edges[p][j];
                    if(value+1<cost[offset+e.q]) {
                        cost[offset+e.q]=int16_t(value+1);
                        action[offset+e.q]={int16_t(p),0,e.d,e.l};
                        push(e.q,value+1);
                    }
                }
            }
        }
        ++jump_collection_stats.completed;
        const int all=masks-1,offset=all*floors;
        const int fixed_cost=cost[offset+sources[0]];
        if(incumbent.score>0&&fixed_cost<int(incumbent.moves.size())) {
            ++jump_collection_stats.fixed_root_improvements;
            jump_collection_stats.fixed_root_saved+=int(incumbent.moves.size())-fixed_cost;
        }
        int root=-1,best_gain=0;
        double best_score=incumbent.score;
        for(int p=0;p<floors;p++)if(background[p]==0&&allowed(p)&&cost[offset+p]<infinite_cost) {
            const int steps=cost[offset+p];
            const int candidate_gain=old-steps-board_info.floor_dist[p][board_info.nest_pos_by_code[color]];
            if(candidate_gain<=0)continue;
            const double score=candidate_gain*weight[min(steps,2*max_cells)];
            if(score>best_score){root=p;best_score=score;best_gain=candidate_gain;}
        }
        if(root<0)return result;
        // Reconstruction uses the physical color tower, not selected token IDs.
        State trial=initial;
        vector<Move> moves;moves.reserve(cost[offset+root]);
        function<void(int,int)> emit=[&](int mask,int target) {
            vector<pair<int,Action>> path;
            int p=target;
            while(action[mask*floors+p].previous>=0) {
                Action a=action[mask*floors+p];path.push_back({p,a});p=a.previous;
            }
            const int part=action[mask*floors+p].part;
            if(part){emit(part,p);emit(mask^part,p);}
            else if((mask&(mask-1))||p!=sources[__builtin_ctz(unsigned(mask))])
                throw logic_error("collection DP origin mismatch");
            for(auto it=path.rbegin();it!=path.rend();it++) {
                const Action a=it->second;
                const int keep=height(trial[a.previous])-amount[mask];
                if(keep<background[a.previous]||
                   mono_color_code(trial[a.previous]>>(4*keep))!=color)
                    throw logic_error("collection moving load mismatch");
                Move m{a.previous,uint8_t(keep),a.d,a.l};
                board_info.apply(trial,m);moves.push_back(m);
            }
        };
        emit(all,root);
        if(int(moves.size())!=cost[offset+root])throw logic_error("collection DP cost mismatch");
        array<TowerBits,max_cells> expected{};
        for(int p=0;p<floors;p++)expected[p]=initial[p];
        for(int i=0;i<count;i++)expected[sources[i]]=0;
        expected[root]=0x11111111u*unsigned(color)&tower_mask[pieces];
        for(int p=0;p<floors;p++)if(trial[p]!=expected[p])throw logic_error("collection endpoint mismatch");
        result.score=best_score;result.moves=move(moves);
        result.jump_collection=true;result.collection_root_changed=root!=sources[0];
        result.collection_jumps=count_if(result.moves.begin(),result.moves.end(),[](Move m){return m.l>1;});
        gain=best_gain;
        ++jump_collection_stats.improved_plans;
        jump_collection_stats.changed_roots+=result.collection_root_changed;
        return result;
    }
};

}
