    MergePlan incumbent=plan_collection_tree(candidate,gain);
    if(candidate.count>6){++jump_collection_stats.large_skips;return incumbent;}
    const double begin=time_keeper.exact_elapsed_sec();
    const double remaining=PROGRAM_TIME_LIMIT_SEC*0.025-jump_collection_stats.seconds;
    if(remaining<=0||begin>=search_end){++jump_collection_stats.budget_skips;return incumbent;}
    const double deadline=min(search_end,begin+min(remaining,PROGRAM_TIME_LIMIT_SEC*0.002));
    struct Timer {
        double begin;
        ~Timer(){jump_collection_stats.seconds+=time_keeper.exact_elapsed_sec()-begin;}
    } timer{begin};
    array<int,8> sources{};int old=0;
    for(int j=0;j<candidate.count;j++) {
        const Group& g=groups[candidate.ids[j]];
        sources[j]=g.p;old+=g.value;
    }
    const int color=mono_color_code(groups[candidate.ids[0]].word);
